def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def reproduce(record, root):
    parent=root/record['parent']['path']
    raw=parent.read_bytes()
    if digest(raw)!=record['parent']['sha256']:
        raise ValueError('The complete original source differs: '+str(parent))
    text=raw.decode('utf-8')
    for item in record['patches']:
        if text.count(item['before'])!=item['count']:
            raise ValueError('Complete literal forward replacement count differs')
        text=text.replace(item['before'],item['after'])
    result=text.encode('utf-8')
    expected=record['output']
    if (len(result)!=expected['bytes'] or len(result)>=100000
            or digest(result)!=expected['sha256']):
        raise ValueError('The entire independent output differs: '+expected['name'])
    inverse=text
    for item in reversed(record['patches']):
        if inverse.count(item['after'])!=item['count']:
            raise ValueError('Complete literal reverse replacement count differs')
        inverse=inverse.replace(item['after'],item['before'])
    if inverse.encode('utf-8')!=raw:
        raise ValueError('The inverse must restore every original source byte')
    return result


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,required=True)
    parser.add_argument('--outdir',type=Path,required=True)
    parser.add_argument('--verify-existing',action='store_true')
    args=parser.parse_args()
    root=args.repo.resolve()/'topics/visible-flex-larger-amplitude'
    out=args.outdir.resolve()
    results=[]
    for record in MANIFEST['records']:
        raw=reproduce(record,root)
        path=out/record['output']['name']
        if args.verify_existing:
            if path.read_bytes()!=raw:
                raise ValueError('The complete existing output differs: '+str(path))
        else:
            out.mkdir(parents=True,exist_ok=True)
            if path.exists() and path.read_bytes()!=raw:
                raise FileExistsError('Do not overwrite another source: '+str(path))
            if not path.exists():
                path.write_bytes(raw)
        results.append(dict(role=record['role'],path=str(path),
            complete_parent_sha256=record['parent']['sha256'],
            bytes=len(raw),sha256=digest(raw),whole_forward_and_inverse_equal=True))
    print(json.dumps(dict(schema=MANIFEST['schema'],complete_source_count=len(results),
        complete_sources=results,scientific_imports_or_evaluations=0,
        Python_AST_or_execution_performed=False),sort_keys=True,indent=2))


if __name__=='__main__':
    main()
